const cfg = $('Configuração').first().json;
const p = $('Ler proposta pela ligação').first().json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const moldura = (titulo, corpo) => '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(titulo) + '</title></head><body style="font-family:Arial,sans-serif;max-width:560px;margin:40px auto;padding:0 16px;color:#222"><h2>' + esc(titulo) + '</h2>' + corpo + '</body></html>';
const resposta = (http, titulo, corpo) => [{ json: { acao: 'resposta', http, html: moldura(titulo, corpo) } }];
const invalida = () => resposta(404, 'Ligação inválida / Invalid link', '<p>Esta ligação não é válida ou já não está disponível. Por favor contacte-nos.</p><p>This link is not valid or is no longer available. Please contact us.</p>');
if (!cfg.chave_ok || !p || !p.id) return invalida();
const pt = ['PT', 'BR', 'AO', 'MZ'].includes(String(p.destino_pais || '').toUpperCase());
const L = pt
  ? { ja: 'Encomenda já confirmada', jaTxt: 'A proposta ' + p.codigo + ' já foi confirmada. Obrigado.', exp: 'Ligação expirada', expTxt: 'Esta ligação expirou. Por favor contacte-nos para renovar a proposta.', tit: 'Confirmar encomenda', resumo: 'Vai confirmar a seguinte proposta:', prod: 'Produto', q: 'Quantidade', dest: 'Destino', inc: 'Incoterm', tot: 'Valor total', btn: 'Confirmar encomenda', nota: 'Ao confirmar, a nossa equipa recebe a encomenda e planeia a expedição.' }
  : { ja: 'Order already confirmed', jaTxt: 'Proposal ' + p.codigo + ' has already been confirmed. Thank you.', exp: 'Link expired', expTxt: 'This link has expired. Please contact us to renew the proposal.', tit: 'Confirm order', resumo: 'You are about to confirm the following proposal:', prod: 'Product', q: 'Quantity', dest: 'Destination', inc: 'Incoterm', tot: 'Total amount', btn: 'Confirm order', nota: 'Once confirmed, our team receives the order and plans the shipment.' };
if (['aceite', 'em_expedicao', 'concluida'].includes(p.estado)) return resposta(200, L.ja, '<p>' + esc(L.jaTxt) + '</p>');
if (p.estado !== 'enviada') return invalida();
if (new Date(p.token_expira_em) < new Date()) return resposta(410, L.exp, '<p>' + esc(L.expTxt) + '</p>');
if (cfg.confirmar) return [{ json: { acao: 'confirmar', proposta_id: p.id, codigo: p.codigo } }];
const linha = (k, v) => '<tr><td style="padding:4px 16px 4px 0"><b>' + esc(k) + '</b></td><td>' + esc(v) + '</td></tr>';
const valor = p.preco_final != null ? Number(p.preco_final).toFixed(2) + ' ' + (p.moeda || 'EUR') : '-';
const link = cfg.url_base + '?t=' + encodeURIComponent(cfg.chave) + '&ok=1';
return resposta(200, L.tit, '<p>' + esc(L.resumo) + '</p><table>' + linha('Ref.', p.codigo) + linha(L.prod, p.produto) + linha(L.q, p.quantidade + ' ' + (p.unidade || 'kg')) + linha(L.dest, p.destino_pais) + linha(L.inc, p.incoterm) + linha(L.tot, valor) + '</table><p><a href="' + link + '" style="display:inline-block;background:#2f6b4f;color:#fff;padding:12px 22px;border-radius:6px;text-decoration:none">' + esc(L.btn) + '</a></p><p style="color:#666;font-size:13px">' + esc(L.nota) + '</p>');

const cfg = $('Configuração').first().json;
const p = $('Ler proposta pela ligação').first().json;
const r = $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const moldura = (titulo, corpo) => '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(titulo) + '</title></head><body style="font-family:Arial,sans-serif;max-width:560px;margin:40px auto;padding:0 16px;color:#222"><h2>' + esc(titulo) + '</h2>' + corpo + '</body></html>';
const pt = ['PT', 'BR', 'AO', 'MZ'].includes(String(p.destino_pais || '').toUpperCase());
if (!r || !r.id) {
  return [{ json: { confirmou: false, http: 200, html: moldura(pt ? 'Encomenda já confirmada' : 'Order already confirmed', '<p>' + esc(pt ? 'A proposta ' + p.codigo + ' já foi confirmada. Obrigado.' : 'Proposal ' + p.codigo + ' has already been confirmed. Thank you.') + '</p>') } }];
}
const teste = !!cfg.destinatario_teste;
const html = moldura(pt ? 'Encomenda confirmada' : 'Order confirmed', '<p>' + esc(pt ? 'Obrigado. A proposta ' + p.codigo + ' foi confirmada. A nossa equipa vai planear a expedição e enviar-lhe o plano final.' : 'Thank you. Proposal ' + p.codigo + ' has been confirmed. Our team will plan the shipment and send you the final plan.') + '</p>');
const link = cfg.url_form + '?codigo=' + encodeURIComponent(p.codigo);
const linha = (k, v) => '<tr><td style="padding:4px 16px 4px 0"><b>' + k + '</b></td><td>' + esc(v) + '</td></tr>';
const assunto = (teste ? '[TESTE] ' : '') + '[' + p.codigo + '] Encomenda confirmada - planear expedição';
const corpo = (teste ? '<p><i>Email de teste.</i></p>' : '') + '<p>O cliente confirmou a proposta <b>' + esc(p.codigo) + '</b>. Falta planear a expedição.</p><table>' + linha('Cliente', p.cliente) + linha('Produto', p.produto) + linha('Quantidade', p.quantidade + ' ' + (p.unidade || 'kg')) + linha('Embalagem', p.embalagem) + linha('Incoterm', p.incoterm) + linha('Destino', p.destino_pais) + '</table><p>Preencha o plano (tempo de produção, stock, data de recolha, modo e transportadora) neste formulário: <a href="' + link + '">' + esc(link) + '</a></p><p>Cumprimentos,<br>Sistema de propostas (mensagem automática)</p>';
const slack = '✅ Proposta *' + p.codigo + '* confirmada pelo cliente · ' + p.produto + ' · destino ' + p.destino_pais + ' · expedição por planear' + (teste ? ' · (teste)' : '');
return [{ json: { confirmou: true, http: 200, html, codigo: p.codigo, proposta_id: p.id, assunto, corpo_html: corpo, para: teste ? cfg.destinatario_teste : cfg.email_madalena, cc: teste ? cfg.destinatario_teste : cfg.email_barbara, slack_texto: slack } }];
